package br.com.confirmacao.scheduleblock.domain;
import br.com.confirmacao.professional.domain.Professional;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity @Table(name="schedule_blocks") public class ScheduleBlock{@Id private UUID id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="professional_id",nullable=false)private Professional professional;@Column(name="starts_at",nullable=false)private Instant startsAt;@Column(name="ends_at",nullable=false)private Instant endsAt;@Column(length=500)private String reason;@Column(name="created_at",nullable=false)private Instant createdAt;protected ScheduleBlock(){}public ScheduleBlock(Professional p,Instant start,Instant end,String reason){if(start==null||end==null||!end.isAfter(start))throw new IllegalArgumentException("O horário final deve ser posterior ao inicial");id=UUID.randomUUID();professional=p;startsAt=start;endsAt=end;this.reason=reason==null||reason.isBlank()?null:reason.trim();createdAt=Instant.now();}public UUID getId(){return id;}public Instant getStartsAt(){return startsAt;}public Instant getEndsAt(){return endsAt;}public String getReason(){return reason;}}
